import torch
import torch.nn as nn

from avelang_kernels.amdgpu_gemm import gemm_pipeline_transposed_b


def avelang_matmul(A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
    assert A.is_cuda and B.is_cuda, "Tensors must be on CUDA/HIP device."

    A = A.to(torch.bfloat16).contiguous()
    B = B.to(torch.bfloat16).contiguous()

    M, K = A.shape
    K2, N = B.shape
    assert K == K2, f"K dimension mismatch: {K} vs {K2}"

    # The reference gemm expects B in (N, K) transposed layout
    B_t = B.T.contiguous()

    return gemm_pipeline_transposed_b(A, B_t)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A, B):
        return avelang_matmul(A, B)
